(function(){"use strict";var endpoint="/api/event";function send(name,props){var body=JSON.stringify({n:name,u:location.href,d:location.hostname,r:document.referrer,p:props||{}});if(navigator.sendBeacon&&navigator.sendBeacon(endpoint,new Blob([body],{type:"text/plain"}))){return;}fetch(endpoint,{method:"POST",headers:{"Content-Type":"text/plain"},body:body,keepalive:true});}function wrap(method){return function(){var result=method.apply(history,arguments);send("pageview");return result;};}history.pushState=wrap(history.pushState);history.replaceState=wrap(history.replaceState);addEventListener("popstate",function(){send("pageview");});var panel=window.panel=window.panel||{};panel.track=send;send("pageview");}());
